"use client";

import { useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import {
  ArrowDownToLine, ArrowRight, ArrowUpRight, CheckCircle2, ChevronRight, Clock3,
  Database, FileBarChart2, FlaskConical, Layers3, Loader2, LogOut,
  Menu, Moon, Plus, Radio, RefreshCw, Search,
  Settings2, ShieldCheck, Sun, Target, TrendingDown, TrendingUp,
  Users, Wallet, X,
} from "lucide-react";
import { Area, AreaChart, CartesianGrid, ReferenceLine, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import type { AppState, SegmentFilter, Simulation, Workspace } from "@/domain/types";
import { RESULT_LABELS } from "@/domain/types";
import { bankroll, decision, pickStats, report } from "@/domain/calculations";
import { EntityForms, type FormKind } from "@/components/entity-forms";
import { SourcesView } from "@/components/sources-view";
import { SettingsView } from "@/components/settings-view";
import { BacktestView } from "@/components/backtest-view";
import { TipstersView } from "@/components/tipsters-view";
import { RadarView } from "@/components/radar-view";
import { DecisionDetail } from "@/components/decision-detail";
import { ProbabilityCalculator } from "@/components/probability-calculator";
import { SpecialtiesView } from "@/components/specialties-view";
import { TipsterProfile } from "@/components/tipster-detail";
import type { ProofLevel } from "@/domain/tipster-analysis";

type View = "radar" | "tipsters" | "specialties" | "reports" | "simulations" | "bankroll" | "sources" | "settings";
type ModalState = { type: "form"; kind: FormKind; initial?: Record<string, unknown> } | { type: "pick"; id: string } | { type: "tipster"; id: string; level?: ProofLevel; simulationId?: string } | { type: "simulation"; id: string } | { type: "reference"; id: string } | null;
const NAV: { id: View; label: string; icon: typeof Radio }[] = [
  { id: "radar", label: "Radar", icon: Radio }, { id: "tipsters", label: "Tipsters", icon: Users },
  { id: "specialties", label: "Spécialités", icon: Layers3 }, { id: "reports", label: "Rapports", icon: FileBarChart2 },
  { id: "simulations", label: "Simulations & stratégies", icon: FlaskConical }, { id: "bankroll", label: "Mes paris & bankroll", icon: Wallet },
  { id: "sources", label: "Sources & imports", icon: Database }, { id: "settings", label: "Paramètres", icon: Settings2 },
];
const VIEW_COPY: Record<View, { eyebrow: string; title: string; description: string }> = {
  radar: { eyebrow: "VOTRE OBSERVATOIRE PERSONNEL", title: "Le radar", description: "Les bons dossiers commencent par des données solides." },
  tipsters: { eyebrow: "COMPRENDRE AVANT DE SUIVRE", title: "Les tipsters", description: "Des profils comparables. Des performances replacées dans leur contexte." },
  specialties: { eyebrow: "AFFINER VOTRE REGARD", title: "Spécialités & analyses", description: "Explorez les segments, puis confrontez vos hypothèses aux prochaines observations." },
  reports: { eyebrow: "DES CONSTATS, AVEC LEURS SOURCES", title: "Les rapports", description: "Une synthèse déterministe de vos données, de leurs écarts et de leurs limites." },
  simulations: { eyebrow: "EXPLORER SANS ENGAGER", title: "Simulations & stratégies", description: "Comparez les mises, formalisez vos règles et gardez une trace de vos décisions." },
  bankroll: { eyebrow: "VOTRE RÉSULTAT RÉEL", title: "Mes paris & bankroll", description: "Chaque ticket, chaque mouvement. Une comptabilité au centime." },
  sources: { eyebrow: "LA QUALITÉ COMMENCE À LA SOURCE", title: "Sources & imports", description: "Centralisez vos données avec une provenance explicite et des imports contrôlés." },
  settings: { eyebrow: "UN CADRE QUI VOUS RESSEMBLE", title: "Les paramètres", description: "Définissez vos limites et les conventions de votre espace personnel." },
};
const FORM_NAMES: Record<FormKind, string> = { tipster: "Ajouter un tipster", pick: "Enregistrer un pronostic", quote: "Observer une cote Winamax", ticket: "Enregistrer un ticket réel", ledger: "Ajouter un mouvement", strategy: "Définir une stratégie", simulation: "Créer une simulation" };
const euro = (cents: number | null | undefined, signed = false) => cents == null || !Number.isFinite(cents) ? "Non applicable" : `${signed && cents > 0 ? "+" : ""}${new Intl.NumberFormat("fr-FR", { style: "currency", currency: "EUR" }).format(cents / 100)}`;
const decimal = (value: number | null | undefined, digits = 2) => value == null || !Number.isFinite(value) ? "—" : new Intl.NumberFormat("fr-FR", { maximumFractionDigits: digits, minimumFractionDigits: digits }).format(value);
const pct = (value: number | null | undefined, signed = false) => value == null || !Number.isFinite(value) ? "Non applicable" : `${signed && value > 0 ? "+" : ""}${decimal(value * 100, 1)} %`;
const units = (value: number, signed = true) => `${signed && value > 0 ? "+" : ""}${decimal(value)} u`;
const dateTime = (value: string | null | undefined, full = false) => !value || !Number.isFinite(Date.parse(value)) ? "Non renseigné" : new Intl.DateTimeFormat("fr-FR", { timeZone: "Europe/Paris", day: "2-digit", month: full ? "long" : "short", ...(full ? { year: "numeric" as const } : {}), hour: "2-digit", minute: "2-digit" }).format(new Date(value));
const shortDate = (value: string) => !Number.isFinite(Date.parse(value)) ? "—" : new Intl.DateTimeFormat("fr-FR", { timeZone: "Europe/Paris", day: "2-digit", month: "short" }).format(new Date(value));
function Badge({ children, color = "muted" }: { children: ReactNode; color?: "teal" | "amber" | "red" | "muted" | "outline" }) { return <span className={`badge badge-${color}`}>{children}</span>; }
function Metric({ label, value, note, icon: Icon, tone }: { label: string; value: ReactNode; note: ReactNode; icon: typeof Radio; tone?: string }) { return <div className="metric"><div className="metric-top"><span>{label}</span><span className="metric-icon"><Icon /></span></div><div className={`metric-value ${tone ?? ""}`}>{value}</div><div className="metric-note">{note}</div></div>; }
function Empty({ title, text, action, onAction, icon: Icon = Radio }: { title: string; text: string; action?: string; onAction?: () => void; icon?: typeof Radio }) { return <div className="empty-state"><div className="empty-icon"><Icon size={23} strokeWidth={1.5} /></div><h3>{title}</h3><p>{text}</p>{action && <button className="button button-primary" onClick={onAction}><Plus />{action}</button>}</div>; }
function Chart({ points, unit = "u" }: { points: { at: string; value: number }[]; unit?: string }) { return points.length ? <div className="chart" role="img" aria-label={`Courbe de performance : ${points.length} observations, dernière valeur ${decimal(points.at(-1)?.value)} ${unit}`}><ResponsiveContainer width="100%" height="100%"><AreaChart data={points} margin={{ top: 16, right: 16, left: -16, bottom: 2 }}><defs><linearGradient id={`performance-${unit.replace(/\W/g, "")}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#199b80" stopOpacity={0.18} /><stop offset="100%" stopColor="#199b80" stopOpacity={0} /></linearGradient></defs><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="var(--line)" /><XAxis dataKey="at" tickFormatter={shortDate} minTickGap={40} axisLine={false} tickLine={false} tick={{ fontSize: 9, fill: "var(--muted)" }} /><YAxis axisLine={false} tickLine={false} tick={{ fontSize: 9, fill: "var(--muted)" }} domain={["auto", "auto"]} /><Tooltip labelFormatter={(value) => dateTime(String(value))} formatter={(value) => [`${decimal(Number(value))} ${unit}`, "Performance"]} contentStyle={{ background: "var(--panel)", color: "var(--ink)", border: "1px solid var(--line)", borderRadius: 7, fontSize: 11 }} /><ReferenceLine y={unit === "u" ? 0 : 100} stroke="var(--line)" /><Area type="linear" dataKey="value" stroke="#15967c" strokeWidth={2} fill={`url(#performance-${unit.replace(/\W/g, "")})`} isAnimationActive={false} /></AreaChart></ResponsiveContainer></div> : <div className="mini-empty">La courbe apparaîtra après vos premières observations réglées.</div>; }
function Dialog({ title, children, onClose, theme }: { title: string; children: ReactNode; onClose: () => void; theme: string }) { const ref = useRef<HTMLDialogElement>(null); useEffect(() => { const dialog = ref.current; if (dialog && !dialog.open) dialog.showModal(); return () => { if (dialog?.open) dialog.close(); }; }, []); return <dialog className="modal" data-theme={theme} ref={ref} aria-label={title} onCancel={onClose} onClick={(event) => { if (event.target === event.currentTarget) { const rect = event.currentTarget.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) onClose(); } }}><div className="modal-head"><h2>{title}</h2><button className="icon-button" onClick={onClose} aria-label="Fermer"><X /></button></div><div className="modal-body">{children}</div></dialog>; }

export default function Home() {
  const [workspace, setWorkspace] = useState<Workspace>("personal");
  const [state, setState] = useState<AppState | null>(null);
  const [view, setView] = useState<View>("radar");
  const [theme, setTheme] = useState("light");
  const [mobileNav, setMobileNav] = useState(false);
  const [isMobile, setIsMobile] = useState(false);
  const [, setFreshnessTick] = useState(0);
  const [search, setSearch] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [demoLoading, setDemoLoading] = useState(false);
  const [modal, setModal] = useState<ModalState>(null);
  const [toast, setToast] = useState("");
  const [ticketFilter, setTicketFilter] = useState("all");
  const [segment, setSegment] = useState<SegmentFilter>({});
  const [analysisPeriod, setAnalysisPeriod] = useState<"all" | "discovery" | "validation">("all");
  const [specialtyProof, setSpecialtyProof] = useState<ProofLevel>("declared");
  const [strategyId, setStrategyId] = useState("");
  const [reportPeriod, setReportPeriod] = useState("all");
  const [bankTab, setBankTab] = useState("tickets");
  const searchRef = useRef<HTMLInputElement>(null);
  const refresh = useCallback(async (selected: Workspace = workspace) => {
    const response = await fetch(`/api/data?workspace=${selected}`, { cache: "no-store" });
    if (response.status === 401) { window.location.assign("/login"); return; }
    const json = await response.json();
    if (!response.ok) throw new Error(json.error ?? "Impossible de charger les données.");
    setState(json);
  }, [workspace]);
  useEffect(() => { setLoading(true); setError(""); setModal(null); refresh().catch((cause: Error) => setError(cause.message)).finally(() => setLoading(false)); }, [refresh]);
  useEffect(() => { const saved = localStorage.getItem("prisme-theme"); if (saved === "dark" || saved === "light") setTheme(saved); const handle = (event: KeyboardEvent) => { if ((event.ctrlKey || event.metaKey) && event.key === "k") { event.preventDefault(); searchRef.current?.focus(); } }; window.addEventListener("keydown", handle); return () => window.removeEventListener("keydown", handle); }, []);
  useEffect(() => { const media = window.matchMedia("(max-width: 760px)"); const update = () => setIsMobile(media.matches); update(); media.addEventListener("change", update); const freshness = window.setInterval(() => setFreshnessTick((value) => value + 1), 30000); const escape = (event: KeyboardEvent) => { if (event.key === "Escape") setMobileNav(false); }; window.addEventListener("keydown", escape); return () => { media.removeEventListener("change", update); clearInterval(freshness); window.removeEventListener("keydown", escape); }; }, []);
  useEffect(() => { if (!toast) return; const timeout = window.setTimeout(() => setToast(""), 4500); return () => clearTimeout(timeout); }, [toast]);
  function navigate(next: View) { setView(next); setMobileNav(false); setSearch(""); window.scrollTo({ top: 0, behavior: "instant" }); }
  function toggleTheme() { const next = theme === "light" ? "dark" : "light"; setTheme(next); localStorage.setItem("prisme-theme", next); }
  async function mutate(action: string, payload: Record<string, unknown>): Promise<unknown> {
    const response = await fetch("/api/actions", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ workspace, action, payload }) });
    if (response.status === 401) { window.location.assign("/login"); throw new Error("Votre session a expiré."); }
    const json = await response.json(); if (!response.ok) throw new Error(json.error ?? "L’enregistrement a échoué.");
    if (action !== "import.preview") {
      await refresh();
      if (action !== "odds.sync") setToast(action === "import.commit" ? "Import enregistré et comptabilité actualisée." : "Enregistrement effectué.");
    }
    return json.result;
  }
  async function openDemo() { setDemoLoading(true); setError(""); try { const response = await fetch("/api/actions", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ workspace: "demo", action: "demo.seed", payload: {} }) }); const body = await response.json(); if (!response.ok) throw new Error(body.error ?? "La démonstration n’a pas pu être chargée."); setLoading(true); setState(null); setWorkspace("demo"); } catch (cause) { setError(cause instanceof Error ? cause.message : "Erreur de chargement."); } finally { setDemoLoading(false); } }
  function openForm(kind: FormKind, initial?: Record<string, unknown>) { setModal({ type: "form", kind, initial }); }
  function openReference(id: string) { if (!state) return; const key = id.replace(/^(pick|ticket|tipster|quote|simulation|ledger|strategy)[:/]/, ""); const pick = state.picks.find((p) => p.id === key); if (pick) setModal({ type: "pick", id: key }); else { const tipster = state.tipsters.find((t) => t.id === key); if (tipster) setModal({ type: "tipster", id: key }); else setModal({ type: "reference", id: key }); } }
  const balance = useMemo(() => state ? bankroll(state) : null, [state]);
  if (loading && !state) return <main className="loading-page"><div className="brand"><span className="brand-mark" />PRISME</div><Loader2 className="spin" size={20} /><p>Ouverture de votre espace…</p></main>;
  if (!state || !balance) return <main className="loading-page"><div className="panel error-card"><Database size={30} /><h2>Votre espace est indisponible</h2><p>{error || "Le chargement n’a pas abouti."}</p><button className="button button-primary" onClick={() => { setLoading(true); setError(""); refresh().catch((cause: Error) => setError(cause.message)).finally(() => setLoading(false)); }}><RefreshCw size={14} />Réessayer</button></div></main>;

  const pending = state.picks.filter((p) => p.result === "open");
  const configured = [state.settings.maxBetPercent, state.settings.maxEventPercent, state.settings.maxExposurePercent, state.settings.dailyLossLimitCents, state.settings.monthlyLossLimitCents].every((limit) => limit !== null && limit > 0);
  const tickets = state.tickets.filter((t) => (ticketFilter === "all" || (ticketFilter === "open" ? t.result === "open" || t.partialCashout : t.result !== "open" && !t.partialCashout)) && `${t.event} ${t.selection} ${t.sourceId}`.toLowerCase().includes(search.toLowerCase())).sort((a, b) => b.placedAt.localeCompare(a.placedAt));
  const page = VIEW_COPY[view];
  return <div className="app-shell" data-theme={theme}>
    <a href="#main" className="skip-link">Aller au contenu</a>
    <button className={`mobile-scrim ${mobileNav ? "visible" : ""}`} aria-label="Fermer le menu" onClick={() => setMobileNav(false)} />
    <aside id="side-navigation" className={`sidebar ${mobileNav ? "open" : ""}`} aria-label="Navigation principale" inert={isMobile && !mobileNav ? true : undefined}><div className="brand"><span className="brand-mark" />PRISME</div><div className="brand-sub">Des données aux décisions</div><div className="sidebar-label">Votre espace d’analyse</div><nav className="navigation">{NAV.map(({ id, label, icon: Icon }) => <button key={id} className={`nav-link ${view === id ? "active" : ""}`} onClick={() => navigate(id)} aria-current={view === id ? "page" : undefined}><Icon strokeWidth={1.6} /><span>{label}</span>{id === "radar" && pending.length > 0 && <span className="nav-count">{pending.length}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="sidebar-note"><b><ShieldCheck size={12} style={{ verticalAlign: "-2px", marginRight: 6 }} />Un cadre, pas une promesse.</b>Observer. Comparer. Décider.<br />Vos prises de pari restent manuelles.</div><div className="profile"><div className="avatar">VP</div><div><div className="profile-name">Votre espace personnel</div><div className="profile-meta">{workspace === "demo" ? "Démonstration isolée" : "Accès privé · EUR"}</div></div><button className="icon-button" style={{ marginLeft: "auto" }} title="Se déconnecter" aria-label="Se déconnecter" onClick={async () => { try { const response = await fetch("/api/logout", { method: "POST" }); if (response.ok) window.location.assign("/login"); else setError("La déconnexion a échoué."); } catch { setError("La déconnexion a échoué."); } }}><LogOut /></button></div></div></aside>
    <div className="workspace"><header className="topbar"><button className="icon-button mobile-toggle" aria-label="Ouvrir le menu" aria-controls="side-navigation" aria-expanded={mobileNav} onClick={() => setMobileNav(true)}><Menu /></button><div className="breadcrumb"><span>Espace personnel</span><ChevronRight size={12} /><strong>{NAV.find((n) => n.id === view)?.label}</strong></div><div className="topbar-tools"><label className="search-box"><Search size={14} /><input ref={searchRef} aria-label="Rechercher un pronostic, tipster ou ticket" placeholder="Rechercher…" value={search} onChange={(event) => { setSearch(event.target.value); if (!["radar", "tipsters", "bankroll"].includes(view)) setView("radar"); }} /><kbd>⌘ K</kbd></label><span className="topbar-divider" /><span className="local-status"><span className="status-dot" />Données enregistrées</span><button className="icon-button" aria-label={theme === "light" ? "Activer le thème sombre" : "Activer le thème clair"} title="Changer de thème" onClick={toggleTheme}>{theme === "light" ? <Moon /> : <Sun />}</button><button className="icon-button" aria-label="Actualiser les données" title="Actualiser" onClick={() => refresh().then(() => setToast("Données actualisées.")).catch((cause: Error) => setError(cause.message))}><RefreshCw /></button><span className="avatar" style={{ width: 30, height: 30, background: "var(--teal-soft)", color: "var(--teal)" }}>VP</span></div></header>
    <main className="main-content" id="main">
      {workspace === "demo" && <div className="demo-banner"><span><FlaskConical size={13} /><b>DÉMONSTRATION</b> · Données entièrement fictives, séparées de votre espace personnel.</span><button onClick={() => { setLoading(true); setState(null); setWorkspace("personal"); setSearch(""); setSegment({}); setStrategyId(""); }}>Revenir à mes données</button></div>}
      {error && <div className="notice notice-error" role="alert" style={{ marginBottom: 20, display: "flex", alignItems: "center", justifyContent: "space-between" }}>{error}<button className="icon-button" aria-label="Masquer l’erreur" onClick={() => setError("")}><X /></button></div>}
      <div className="page-intro"><div><div className="eyebrow">{page.eyebrow}</div><h1>{page.title}</h1><p>{page.description}</p></div><div className="intro-actions">{view === "radar" && <><button className="button button-secondary" onClick={() => navigate("sources")}><ArrowDownToLine />Importer des données</button><button className="button button-primary" onClick={() => state.tipsters.length ? openForm("pick") : openForm("tipster")}><Plus />{state.tipsters.length ? "Nouveau pronostic" : "Ajouter un tipster"}</button></>}{view === "tipsters" && <button className="button button-primary" onClick={() => openForm("tipster")}><Plus />Ajouter un tipster</button>}{view === "simulations" && <button className="button button-primary" onClick={() => openForm("simulation")}><Plus />Nouvelle simulation</button>}{view === "bankroll" && <><button className="button button-secondary" onClick={() => openForm("ledger")}><Plus />Mouvement</button><button className="button button-primary" onClick={() => openForm("ticket")}><Plus />Ticket réel</button></>}{view === "reports" && <a className="button button-secondary" href={`/api/export?workspace=${workspace}`} download><ArrowDownToLine />Exporter les données</a>}</div></div>

      {view === "radar" && (
        <RadarView
          key={workspace}
          state={state}
          search={search}
          demoLoading={demoLoading}
          onOpenDemo={openDemo}
          onOpenPick={(id) => setModal({ type: "pick", id })}
          onOpenTipster={(id) => setModal({ type: "tipster", id })}
          onOpenForm={openForm}
          onNavigate={navigate}
          onExploreStrategy={(id, filter) => {
            setStrategyId(id);
            setSegment(filter);
            setAnalysisPeriod("validation");
            setSpecialtyProof("observed");
            navigate("specialties");
          }}
          mutate={mutate}
          portfolioChart={<Chart points={balance.series} unit="base 100" />}
        />
      )}

      {view === "tipsters" && (
        <TipstersView
          key={workspace}
          state={state}
          search={search}
          onOpenTipster={(id, level, simulationId) => setModal({ type: "tipster", id, level, simulationId })}
          onOpenPick={(id) => setModal({ type: "pick", id })}
          onCreateTipster={() => openForm("tipster")}
          onExploreTipster={(id, level) => {
            setSegment({ tipsterId: id });
            setStrategyId("");
            setAnalysisPeriod("all");
            setSpecialtyProof(level);
            navigate("specialties");
          }}
        />
      )}
      {view === "specialties" && (
        <SpecialtiesView
          key={workspace}
          state={state}
          initialFilter={segment}
          initialStrategyId={strategyId}
          initialProof={specialtyProof}
          initialPhase={analysisPeriod}
          onOpenPick={(id) => setModal({ type: "pick", id })}
          onOpenReference={openReference}
          onCreateStrategy={(filter) => openForm("strategy", { filter })}
          onSaveExploration={(payload) => mutate("analysis.explore", payload)}
        />
      )}

      {view === "reports" && <ReportsView state={state} period={reportPeriod} setPeriod={setReportPeriod} openReference={openReference} />}
      {view === "simulations" && <div className="stack">{(!configured || state.settings.paused) && <div className="notice notice-warning"><ShieldCheck />{state.settings.paused ? "Les suggestions sont en pause. Les nouvelles allocations seront nulles jusqu’à la reprise dans vos paramètres." : "Renseignez le capital, les plafonds d’exposition et les limites de pertes dans Paramètres avant d’allouer une mise simulée."}<button className="text-link" style={{ marginLeft: 12 }} onClick={() => navigate("settings")}>Paramètres<ArrowRight /></button></div>}<div className="view-grid"><section className="panel"><div className="panel-head"><div><h2>Vos simulations enregistrées</h2><p>Un panier partagé, une allocation au centime, aucun mouvement réel.</p></div><FlaskConical size={18} color="var(--muted)" /></div>{state.simulations.length ? [...state.simulations].reverse().map((simulation) => <div className="simulation-line" key={simulation.id}><div><button className="table-button" onClick={() => setModal({ type: "simulation", id: simulation.id })}>{simulation.name}</button><p>{dateTime(simulation.createdAt)} · {simulation.method === "fixed" ? "Mise fixe" : simulation.method === "percent" ? "Pourcentage du capital" : "Kelly fractionné"}</p></div><div style={{ textAlign: "right" }}><strong style={{ fontSize: 13 }}>{euro(simulation.allocations.reduce((sum, a) => sum + a.stakeCents, 0))}</strong><p>{simulation.allocations.length} décisions</p></div></div>) : <Empty icon={FlaskConical} title="Votre laboratoire de décisions" text="Enregistrez des cotes observées, puis comparez les mises sur un panier de pronostics. Les probabilités restent des hypothèses explicites." action="Créer une simulation" onAction={() => openForm("simulation")} />}</section><section className="panel"><div className="panel-head"><div><h2>Stratégies prospectives</h2><p>Conservez les règles et la frontière entre découverte et validation.</p></div><button className="text-link" onClick={() => openForm("strategy")}><Plus />Ajouter</button></div>{state.strategies.length ? state.strategies.map((strategy) => <div className="strategy-card" key={strategy.id} style={{ borderTop: "1px solid var(--line)" }}><h3>{strategy.name}</h3><Badge color={strategy.active ? "teal" : "muted"}>{strategy.active ? "Suivie" : "Inactive"}</Badge><Badge color="amber">Hypothèse à valider</Badge><p className="muted">{Object.entries(strategy.filter).map(([key, value]) => `${key} : ${value}`).join(" · ") || "Tous les pronostics"}</p><p className="muted" style={{ fontSize: 10 }}>Figée : {dateTime(strategy.frozenAt)}<br />Validation : à partir du {dateTime(strategy.validationStart)}</p><button className="text-link" onClick={() => { setStrategyId(strategy.id); setSegment(strategy.filter); setAnalysisPeriod("validation"); setSpecialtyProof("observed"); navigate("specialties"); }}>Voir la validation<ArrowRight /></button></div>) : <Empty icon={Target} title="Figez votre première hypothèse" text="Définissez le profil, le marché et les dates avant les nouvelles observations. Aucune stratégie n’est déclarée validée par défaut." action="Définir une stratégie" onAction={() => openForm("strategy")} />}</section></div><BacktestView state={state} openPick={(id) => setModal({ type: "pick", id })} /><ProbabilityCalculator /></div>}

      {view === "bankroll" && <div className="stack"><div className="metric-grid" style={{ marginBottom: 0 }}><Metric label="Cash disponible" value={euro(balance.cashCents)} note="Solde issu du journal financier" icon={Wallet} /><Metric label="Mises cash ouvertes" value={euro(balance.openStakeCents)} note={balance.uncertainOpenCost ? "Coût ouvert incertain — données à compléter" : "Positions valorisées au coût"} icon={Clock3} /><Metric label="Résultat net" value={euro(balance.netProfitCents, true)} note={`Cash : ${euro(balance.profitCashCents, true)}`} icon={TrendingUp} tone={balance.netProfitCents >= 0 ? "positive" : "negative"} /><Metric label="Drawdown maximal" value={pct(balance.drawdownPct)} note={balance.recoveryDays === null ? "Récupération non applicable ou en cours" : `Récupération : ${balance.recoveryDays} jours`} icon={TrendingDown} /></div><div className="view-grid"><section className="panel"><div className="panel-head"><div><h2>Performance du portefeuille</h2><p>Valeur de part · base 100 · dépôts et retraits neutralisés.</p></div></div><Chart points={balance.series} unit="base 100" /><p className="chart-caption">Les positions ouvertes restent au coût. Une nouvelle contribution ne gomme pas un drawdown.</p></section><section className="panel panel-pad"><div className="section-heading"><h2>Le solde, expliqué</h2></div><div className="amount-breakdown"><span>Capital comptable (cash + ouvert)</span><strong>{euro(balance.capitalCents)}</strong></div><div className="amount-breakdown"><span>Résultat cash hors promotions</span><strong>{euro(balance.profitCashCents, true)}</strong></div><div className="amount-breakdown"><span>Résultat promotionnel / freebets</span><strong>{euro(balance.promotionCents, true)}</strong></div><div className="amount-breakdown"><span>Frais enregistrés</span><strong>{euro(balance.feesCents)}</strong></div><div className="amount-breakdown"><span>Solde de compte renseigné</span><strong>{euro(state.settings.reconciliationBalanceCents)}</strong></div><div className="amount-breakdown"><span>Écart de rapprochement</span><strong className={state.settings.reconciliationBalanceCents !== null && state.settings.reconciliationBalanceCents !== balance.cashCents ? "negative" : "positive"}>{state.settings.reconciliationBalanceCents === null ? "À renseigner" : euro(balance.cashCents - state.settings.reconciliationBalanceCents, true)}</strong></div><button className="text-link" style={{ marginTop: 15 }} onClick={() => navigate("settings")}>Renseigner le solde constaté<ArrowRight /></button></section></div><section className="panel"><div className="panel-head"><div><h2>Votre registre personnel</h2><p>Tickets réels et mouvements comptables restent séparés des simulations.</p></div></div><div className="tab-bar"><button className={`tab-button ${bankTab === "tickets" ? "active" : ""}`} onClick={() => setBankTab("tickets")}>Mes tickets · {state.tickets.length}</button><button className={`tab-button ${bankTab === "ledger" ? "active" : ""}`} onClick={() => setBankTab("ledger")}>Journal financier · {state.ledger.length}</button></div>{bankTab === "tickets" ? <><div className="filters">{[["all", "Tous"], ["open", "Ouverts"], ["settled", "Réglés"]].map(([id, name]) => <button key={id} className={`filter-chip ${ticketFilter === id ? "active" : ""}`} onClick={() => setTicketFilter(id)}>{name}</button>)}<span className="muted filter-end" style={{ fontSize: 10 }}>Vue par date de prise du ticket</span></div>{tickets.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Événement / sélection</th><th>Accepté le</th><th>Cote</th><th className="number">Mise</th><th>Statut</th><th className="number">Retours cumulés</th><th className="number">Résultat net</th><th>Action</th></tr></thead><tbody>{tickets.map((ticket) => { const pnl = ticket.returnCents - (ticket.funding === "cash" ? ticket.stakeCents : 0) - ticket.feeCents; return <tr key={ticket.id}><td><button className="table-button" onClick={() => setModal({ type: "reference", id: ticket.id })}>{ticket.event}</button><small>{ticket.selection} · {ticket.market}</small><small>{ticket.sourceId || ticket.id}</small></td><td>{dateTime(ticket.placedAt)}<small>{ticket.bookmaker}</small></td><td>{decimal(ticket.odds)}</td><td className="number">{euro(ticket.stakeCents)}<small>{ticket.funding === "freebet" ? "Freebet — sans débit cash" : "Cash"}</small></td><td><Badge color={ticket.result === "won" ? "teal" : ticket.result === "lost" ? "red" : "muted"}>{ticket.partialCashout ? "Cashout partiel" : RESULT_LABELS[ticket.result]}</Badge></td><td className="number">{euro(ticket.returnCents)}</td><td className={`number ${pnl >= 0 ? "positive" : "negative"}`}>{ticket.result === "open" || ticket.partialCashout ? "Position ouverte" : euro(pnl, true)}</td><td><button className="text-link" onClick={() => openForm("ticket", { ...ticket })}>{ticket.result === "open" || ticket.partialCashout ? "Régler le ticket" : "Corriger"}<ArrowUpRight /></button></td></tr>; })}</tbody></table></div> : <Empty icon={Wallet} title="Votre journal attend son premier ticket" text="Enregistrez uniquement les paris effectivement acceptés par le bookmaker, avec leur source. La mise d’un ticket n’est comptée qu’une fois." action="Enregistrer un ticket" onAction={() => openForm("ticket")} />}</> : state.ledger.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Date comptable</th><th>Nature</th><th>Description / provenance</th><th className="number">Montant cash</th><th>Révision</th></tr></thead><tbody>{[...state.ledger].sort((a, b) => b.at.localeCompare(a.at)).map((entry) => <tr key={entry.id}><td>{dateTime(entry.at)}</td><td><Badge>{({ initial: "Capital initial", deposit: "Dépôt", withdrawal: "Retrait", adjustment: "Ajustement", poker: "Poker / autre activité", fee: "Frais", promotion: "Promotion", ticket_stake: "Mise d’un ticket", ticket_return: "Retour d’un ticket", ticket_fee: "Frais du ticket" })[entry.kind]}</Badge></td><td>{entry.description}{entry.ticketId && <small><button className="text-link" onClick={() => setModal({ type: "reference", id: entry.ticketId! })}>Voir le ticket source</button></small>}</td><td className={`number ${entry.amountCents > 0 ? "positive" : ""}`}>{euro(entry.amountCents, true)}</td><td>{entry.revision}</td></tr>)}</tbody></table></div> : <Empty icon={Wallet} title="Aucun mouvement enregistré" text="Renseignez votre capital initial, puis vos dépôts, retraits et frais. Les flux de capital ne modifient pas le bénéfice des paris." action="Renseigner mon capital" onAction={() => openForm("ledger")} />}<div className="panel-footer"><span>Les règlements sont révisables sans doublon financier. Les frais doivent être enregistrés une seule fois.</span></div></section></div>}
      {view === "sources" && <SourcesView key={workspace} state={state} mutate={mutate} onOpenQuote={(pickId) => openForm("quote", pickId ? { pickId } : undefined)} />}
      {view === "settings" && <SettingsView key={`${workspace}-${state.audit.length}`} state={state} mutate={mutate} />}
      <footer className="footer"><span><ShieldCheck />PRISME · Un outil d’analyse personnel. Les résultats passés ne garantissent pas les résultats futurs.</span><span>EUR · Europe/Paris · Accès privé</span></footer>
    </main></div>
    {toast && <div className="toast" role="status"><CheckCircle2 />{toast}</div>}
    {modal && <Dialog theme={theme} title={modal.type === "form" ? (modal.initial?.id ? "Modifier les données" : FORM_NAMES[modal.kind]) : modal.type === "pick" ? "Fiche de décision" : modal.type === "tipster" ? "Fiche tipster" : modal.type === "simulation" ? "Simulation enregistrée" : "Donnée source"} onClose={() => setModal(null)}>{modal.type === "form" ? <EntityForms key={`${modal.kind}-${String(modal.initial?.id ?? "new")}`} kind={modal.kind} state={state} initial={modal.initial} onSave={async (action, payload) => { await mutate(action, payload); }} onClose={() => setModal(null)} /> : modal.type === "pick" ? <DecisionDetail key={modal.id} pick={state.picks.find((p) => p.id === modal.id)!} state={state} onOpenForm={openForm} onOpenTipster={(id) => setModal({ type: "tipster", id })} onOpenReference={openReference} mutate={mutate} /> : modal.type === "tipster" ? <TipsterProfile key={modal.id} initialProof={modal.level} initialSimulationId={modal.simulationId} tipster={state.tipsters.find((t) => t.id === modal.id)!} state={state} onEdit={() => openForm("tipster", { ...state.tipsters.find((tipster) => tipster.id === modal.id)! })} onAddPick={() => openForm("pick", { tipsterId: modal.id })} onOpenPick={(id) => setModal({ type: "pick", id })} onOpenReference={openReference} /> : modal.type === "simulation" ? <SimulationDetail simulation={state.simulations.find((s) => s.id === modal.id)!} state={state} openPick={(id) => setModal({ type: "pick", id })} /> : <ReferenceDetail id={modal.id} state={state} openForm={openForm} openPick={(id) => setModal({ type: "pick", id })} />}</Dialog>}
  </div>;
}

function SimulationDetail({ simulation, state, openPick }: { simulation: Simulation; state: AppState; openPick: (id: string) => void }) {
  if (!simulation) return <p className="muted">Cette simulation n’est plus disponible.</p>;
  const total = simulation.allocations.reduce((s, a) => s + a.stakeCents, 0);
  const known = simulation.allocations.filter((a) => a.stakeCents > 0).every((a) => a.expectedCents !== null);
  return <div className="stack"><div><div className="eyebrow">SCÉNARIO CONSERVÉ · AUCUN MOUVEMENT RÉEL</div><h2>{simulation.name}</h2><p className="muted" style={{ marginTop: 8 }}>{dateTime(simulation.createdAt, true)} · {simulation.method === "fixed" ? "Mise fixe" : simulation.method === "percent" ? "Pourcentage du capital" : "Kelly fractionné"}</p></div><div className="comparison-grid" style={{ marginTop: 0 }}><div className="calculation-output"><small>Total alloué</small><strong>{euro(total)}</strong></div><div className="calculation-output"><small>Paris avec une allocation</small><strong>{simulation.allocations.filter((a) => a.stakeCents > 0).length}</strong></div><div className="calculation-output"><small>Espérance hypothétique du panier</small><strong>{known && total > 0 ? euro(simulation.allocations.reduce((s, a) => s + (a.expectedCents ?? 0), 0), true) : "Inconnue"}</strong></div></div><div className="notice notice-warning">Les probabilités manuelles sont des hypothèses. Le calcul de mise ne démontre pas d’avantage. Les plafonds s’appliquent au panier complet ; les événements communs restent corrélés.</div><p className="muted">{simulation.assumptions || "Aucune hypothèse complémentaire renseignée."}</p><div className="panel"><div className="table-wrap"><table className="data-table"><thead><tr><th>Pronostic</th><th>Cote</th><th>Probabilité</th><th className="number">Mise</th><th className="number">Espérance</th><th>Décision</th></tr></thead><tbody>{simulation.allocations.map((a, index) => <tr key={`${a.pickId}-${index}`}><td><button className="table-button" onClick={() => openPick(a.pickId)}>{state.picks.find((p) => p.id === a.pickId)?.event ?? a.pickId}</button><small>{state.picks.find((p) => p.id === a.pickId)?.selection}</small></td><td>{decimal(a.odds)}</td><td>{a.probability === null ? "Inconnue" : pct(a.probability)}<small>{a.probabilitySource === "manual" ? "Hypothèse manuelle" : a.probabilitySource ?? "Non renseignée"}</small></td><td className="number">{euro(a.stakeCents)}</td><td className="number">{a.expectedCents === null ? "Inconnue" : euro(a.expectedCents, true)}</td><td style={{ whiteSpace: "normal", minWidth: 180 }}>{a.reason}</td></tr>)}</tbody></table></div></div><details><summary className="muted">Paramètres conservés au moment de la simulation</summary><dl className="detail-list" style={{ marginTop: 12 }}><div className="detail-line"><dt>Plafond par pari / événement / total</dt><dd>{pct(simulation.settingsSnapshot.maxBetPercent)} / {pct(simulation.settingsSnapshot.maxEventPercent)} / {pct(simulation.settingsSnapshot.maxExposurePercent)}</dd></div><div className="detail-line"><dt>Fraction de Kelly</dt><dd>{pct(simulation.settingsSnapshot.kellyFraction)}</dd></div><div className="detail-line"><dt>Mise fixe</dt><dd>{euro(simulation.settingsSnapshot.fixedStakeCents)}</dd></div><div className="detail-line"><dt>Mise proportionnelle</dt><dd>{pct(simulation.settingsSnapshot.stakePercent)}</dd></div><div className="detail-line"><dt>Référence du scénario</dt><dd><code className="reference-code">{simulation.id}</code></dd></div></dl></details></div>;
}

function ReferenceDetail({ id, state, openForm, openPick }: { id: string; state: AppState; openForm: (kind: FormKind, initial?: Record<string, unknown>) => void; openPick: (id: string) => void }) {
  const ticket = state.tickets.find((t) => t.id === id);
  const simulation = state.simulations.find((s) => s.id === id);
  const quote = state.quotes.find((q) => q.id === id);
  const ledger = state.ledger.find((l) => l.id === id);
  const strategy = state.strategies.find((s) => s.id === id);
  if (simulation) return <SimulationDetail simulation={simulation} state={state} openPick={openPick} />;
  if (ticket) return <div className="stack"><div><div className="eyebrow">TICKET RÉEL · {ticket.bookmaker}</div><h2>{ticket.event}</h2><p className="muted" style={{ marginTop: 9 }}>{ticket.selection} · {ticket.market} · {ticket.line || "Sans ligne"}</p></div><Badge color={ticket.result === "won" ? "teal" : ticket.result === "lost" ? "red" : "muted"}>{RESULT_LABELS[ticket.result]}{ticket.partialCashout ? " · cashout partiel" : ""}</Badge><dl className="detail-list"><div className="detail-line"><dt>Identifiant source</dt><dd>{ticket.sourceId || "Non fourni"}</dd></div><div className="detail-line"><dt>Provenance / preuve d’acceptation</dt><dd>{ticket.source}</dd></div><div className="detail-line"><dt>Accepté le</dt><dd>{dateTime(ticket.placedAt, true)}</dd></div><div className="detail-line"><dt>Réglé le</dt><dd>{dateTime(ticket.settledAt, true)}</dd></div><div className="detail-line"><dt>Cote acceptée</dt><dd>{decimal(ticket.odds)}</dd></div><div className="detail-line"><dt>Mise / financement</dt><dd>{euro(ticket.stakeCents)} · {ticket.funding === "cash" ? "Cash" : "Freebet"}</dd></div><div className="detail-line"><dt>Retours cash cumulés</dt><dd>{euro(ticket.returnCents)}</dd></div><div className="detail-line"><dt>Frais</dt><dd>{euro(ticket.feeCents)}</dd></div><div className="detail-line"><dt>Coût encore exposé</dt><dd>{ticket.result === "open" ? euro(ticket.remainingStakeCents ?? (ticket.funding === "cash" ? ticket.stakeCents : 0)) : euro(ticket.remainingStakeCents)}</dd></div><div className="detail-line"><dt>Règles du ticket</dt><dd>{ticket.rules || "Non précisées"}</dd></div><div className="detail-line"><dt>Stratégie</dt><dd>{state.strategies.find((s) => s.id === ticket.strategyId)?.name || "Sans affectation"}</dd></div><div className="detail-line"><dt>Référence interne</dt><dd><code className="reference-code">{ticket.id}</code></dd></div></dl>{ticket.notes && <p className="notice">{ticket.notes}</p>}<div><h3>Modifications conservées</h3>{ticket.revisions.length ? ticket.revisions.map((r, i) => <p className="muted" style={{ marginTop: 8 }} key={i}>{dateTime(r.at)} · {r.description}</p>) : <p className="muted" style={{ marginTop: 8 }}>Aucune révision.</p>}</div><div className="form-actions">{ticket.pickId && <button className="button button-secondary" onClick={() => openPick(ticket.pickId!)}>Voir le pronostic lié</button>}<button className="button button-primary" onClick={() => openForm("ticket", { ...ticket })}>Modifier / régler le ticket</button></div></div>;
  if (quote) return <div className="stack"><h2>Observation Winamax France</h2><dl className="detail-list"><div className="detail-line"><dt>Cote</dt><dd>{decimal(quote.odds)}</dd></div><div className="detail-line"><dt>Observée le</dt><dd>{dateTime(quote.observedAt, true)}</dd></div><div className="detail-line"><dt>Enregistrée le</dt><dd>{dateTime(quote.recordedAt, true)}</dd></div><div className="detail-line"><dt>Source</dt><dd>{quote.source}</dd></div><div className="detail-line"><dt>Marché disponible</dt><dd>{quote.available ? "Oui, lors de l’observation" : "Non"}</dd></div><div className="detail-line"><dt>Identité de marché</dt><dd>{quote.matchConfirmed ? "Confirmée" : "À confirmer"}</dd></div><div className="detail-line"><dt>Clôture</dt><dd>{quote.closing ? "Oui" : "Non"}</dd></div><div className="detail-line"><dt>Référence de clôture sans marge</dt><dd>{pct(quote.referenceProbability)}</dd></div></dl><p className="notice notice-warning">L’observation d’une cote n’est pas une preuve de pari exécuté.</p><button className="button button-primary" onClick={() => openPick(quote.pickId)}>Ouvrir le pronostic</button></div>;
  if (ledger) return <div className="stack"><h2>Mouvement financier</h2><dl className="detail-list"><div className="detail-line"><dt>Description</dt><dd>{ledger.description}</dd></div><div className="detail-line"><dt>Date comptable</dt><dd>{dateTime(ledger.at, true)}</dd></div><div className="detail-line"><dt>Montant cash</dt><dd>{euro(ledger.amountCents, true)}</dd></div><div className="detail-line"><dt>Type</dt><dd>{ledger.kind}</dd></div><div className="detail-line"><dt>Révision</dt><dd>{ledger.revision}</dd></div><div className="detail-line"><dt>Référence</dt><dd><code className="reference-code">{ledger.id}</code></dd></div></dl><p className="notice">{ledger.ticketId ? `Ticket d’origine : ${ledger.ticketId}` : "Mouvement indépendant d’un ticket."}</p></div>;
  if (strategy) return <div className="stack"><h2>{strategy.name}</h2><p className="muted">Figée le {dateTime(strategy.frozenAt)} · Validation à partir du {dateTime(strategy.validationStart)}</p><p>{Object.entries(strategy.filter).map(([k, v]) => `${k} : ${v}`).join(" · ")}</p><p className="notice notice-warning">Hypothèse de suivi, sans affirmation d’avantage prédictif.</p></div>;
  return <div className="notice notice-warning">Référence conservée : {id}. Aucun enregistrement correspondant dans cet espace.</div>;
}

function ReportsView({ state, period, setPeriod, openReference }: { state: AppState; period: string; setPeriod: (period: string) => void; openReference: (id: string) => void }) {
  const generated = useMemo(() => report(state), [state]);
  const dateThreshold = period === "daily" ? Date.now() - 86400000 : period === "weekly" ? Date.now() - 7 * 86400000 : period === "monthly" ? Date.now() - 30 * 86400000 : 0;
  const isInPeriod = (date: string | null) => !!date && Date.parse(date) >= dateThreshold && Date.parse(date) <= Date.now();
  const picks = state.picks.filter((p) => isInPeriod(p.publishedAt));
  const declared = pickStats(picks.filter((p) => p.evidence === "declared"));
  const observed = pickStats(picks.filter((p) => p.evidence === "observed"));
  const sims = state.simulations.filter((s) => isInPeriod(s.createdAt));
  const settled = state.tickets.filter((t) => t.result !== "open" && !t.partialCashout && isInPeriod(t.settledAt));
  const cashProfit = settled.filter((t) => t.funding === "cash").reduce((sum, t) => sum + t.returnCents - t.stakeCents, 0);
  const promoProfit = settled.filter((t) => t.funding === "freebet").reduce((sum, t) => sum + t.returnCents, 0);
  const fees = state.ledger.filter((l) => (l.kind === "fee" || l.kind === "ticket_fee") && isInPeriod(l.at)).reduce((sum, l) => sum - l.amountCents, 0);
  const prospective = state.picks.filter((p) => p.result === "open" && isInPeriod(p.publishedAt));
  const candidates = prospective.filter((p) => decision(p, state).eligible);
  const refName = (ref: string) => { const key = ref.replace(/^[^:]+:/, ""); return state.picks.find((p) => p.id === key)?.event || state.tipsters.find((t) => t.id === key)?.name || state.tickets.find((t) => t.id === key)?.event || state.simulations.find((s) => s.id === key)?.name || (ref.startsWith("quote:") ? "Observation de cote" : ref.startsWith("ledger:") ? "Mouvement financier" : ref); };
  return <div className="stack"><section className="panel"><div className="panel-head"><div><h2>Votre revue de période</h2><p>Données à jour à l’ouverture · synthèse calculée à la demande, sans génération de faits par IA.</p></div><label className="field" style={{ minWidth: 150 }}><span className="sr-only">Période du rapport</span><select className="filter-select" value={period} onChange={(e) => setPeriod(e.target.value)}><option value="all">Depuis l’origine</option><option value="daily">Dernières 24 heures</option><option value="weekly">7 derniers jours</option><option value="monthly">30 derniers jours</option></select></label></div><div className="proof-strip"><div className="proof-item"><small>DÉCLARÉ · PUBLICATIONS</small><strong>{units(declared.profitUnits)}</strong><p>{declared.count} pronostics · rendement {pct(declared.yield)}</p></div><div className="proof-item"><small>OBSERVÉ · PUBLICATIONS</small><strong>{units(observed.profitUnits)}</strong><p>{observed.count} pronostics · rendement {pct(observed.yield)}</p></div><div className="proof-item"><small>SIMULÉ · CRÉATIONS</small><strong>{sims.length}</strong><p>Scénarios enregistrés, aucun débit réel</p></div><div className="proof-item"><small>EXÉCUTÉ · RÈGLEMENTS</small><strong>{euro(cashProfit + promoProfit - fees, true)}</strong><p>{settled.length} tickets clôturés · frais de période</p></div></div><div className="panel-footer"><span>Publications pour les historiques ; créations pour les simulations ; règlements pour les tickets. Les périodes ne décrivent pas la même cohorte.</span></div></section><div className="view-grid"><section className="panel panel-pad"><div className="eyebrow">SYNTHÈSE DES DOSSIERS</div><h2>{candidates.length ? `${candidates.length} dossier(s) à analyser` : "Aucun pari éligible"}</h2><p className="muted" style={{ marginTop: 13 }}>{prospective.length} pronostics encore ouverts dans la période. {candidates.length ? "Une cote récente et une identité de marché confirmée permettent une analyse ; aucune espérance individuelle n’est supposée." : "Les données disponibles ne permettent pas de retenir un dossier immédiatement exploitable. Une abstention reste une décision documentée."}</p><div className="report-refs">{prospective.map((pick) => <button key={pick.id} onClick={() => openReference(`pick:${pick.id}`)}>{pick.event}<ArrowUpRight size={9} style={{ marginLeft: 5 }} /></button>)}</div></section><section className="panel panel-pad"><div className="eyebrow">RÉSULTAT COMPTABLE DE PÉRIODE</div><h2>Les résultats, après coûts</h2><div className="amount-breakdown"><span>Cash hors promotions</span><strong>{euro(cashProfit, true)}</strong></div><div className="amount-breakdown"><span>Retours de freebets clôturés</span><strong>{euro(promoProfit, true)}</strong></div><div className="amount-breakdown"><span>Frais datés de la période</span><strong>{euro(fees)}</strong></div><p className="muted" style={{ fontSize: 10, marginTop: 12 }}>Cashouts partiels ouverts exclus de ce résultat de tickets clôturés. Coûts d’abonnement comptabilisés uniquement via le journal de frais.</p><div className="report-refs">{settled.map((ticket) => <button key={ticket.id} onClick={() => openReference(`ticket:${ticket.id}`)}>{ticket.event}</button>)}{state.ledger.filter((l) => (l.kind === "fee" || l.kind === "ticket_fee") && isInPeriod(l.at)).map((l) => <button key={l.id} onClick={() => openReference(`ledger:${l.id}`)}>{l.description || "Frais comptabilisés"}</button>)}</div></section></div><section className="panel panel-pad"><div className="section-heading"><div><div className="eyebrow">BILAN INTÉGRAL · DEPUIS L’ORIGINE</div><h2>{generated.title}</h2><p>{generated.summary}</p></div><FileBarChart2 size={23} color="var(--teal)" /></div><p className="notice">Les sections ci-dessous couvrent l’ensemble du registre pour préserver le rapprochement financier. Les chiffres sont produits par les fonctions de calcul de l’application.</p>{generated.sections.map((section, index) => <article className="report-section" key={index}><h3>{String(index + 1).padStart(2, "0")} · {section.title}</h3><p>{section.text}</p>{section.refs.length > 0 ? <details style={{ marginTop: 12 }}><summary className="text-link">Consulter les {section.refs.length} données sources</summary><div className="report-refs">{section.refs.map((ref, i) => <button key={`${ref}-${i}`} onClick={() => openReference(ref)} title={ref}>{refName(ref)}<ArrowUpRight size={9} style={{ marginLeft: 5 }} /></button>)}</div></details> : <small className="muted">Aucune donnée source pour cette section.</small>}</article>)}</section></div>;
}
